INSERT OR IGNORE INTO notifications (user_id, kind, body, link, sms, created_at, dedupe_key)
SELECT sa.id, 'absence_teacher',
       'غياب أ. ' || u.name || ' اليوم: ' || CASE n.c WHEN 1 THEN 'حصّة واحدة' WHEN 2 THEN 'حصّتان' ELSE substr('٠١٢٣٤٥٦٧٨٩', n.c + 1, 1) || ' حصص' END || ' بحاجة إلى تغطية',
       '/absences/' || a.id, 0, datetime(a.date || ' 07:06:00', '-3 hours'), 'seed:absence:' || a.id
FROM absences a JOIN users u ON u.id = a.teacher_id JOIN users sa ON sa.role = 'school' AND sa.school_id = u.school_id
JOIN (SELECT s.absence_id, COUNT(*) AS c FROM substitutions s GROUP BY s.absence_id) n ON n.absence_id = a.id
WHERE a.date = (SELECT d FROM demo_days WHERE rn = 1) AND a.teacher_id NOT IN (1021, 1088, 1113, 1122);

INSERT OR IGNORE INTO notifications (user_id, kind, body, link, sms, created_at, dedupe_key)
SELECT s.substitute_teacher_id, 'substitution',
       'تكليفك بتغطية الحصّة ' || CASE t.period WHEN 1 THEN 'الأولى' WHEN 2 THEN 'الثانية' WHEN 3 THEN 'الثالثة' WHEN 4 THEN 'الرابعة' WHEN 5 THEN 'الخامسة' WHEN 6 THEN 'السادسة' ELSE 'السابعة' END || ' اليوم — ' || sec.label || ' · ' || sj.name || COALESCE(' · خطّة الدرس: ' || s.lesson_note, ''),
       '/substitutions/' || s.id, 0, s.approved_at, 'seed:sub:' || s.id
FROM substitutions s JOIN absences a ON a.id = s.absence_id JOIN timetable t ON t.id = s.timetable_id
JOIN sections sec ON sec.id = t.section_id JOIN subjects sj ON sj.id = t.subject_id
WHERE a.date = (SELECT d FROM demo_days WHERE rn = 1) AND s.status = 'approved' AND s.substitute_teacher_id IS NOT NULL;

INSERT OR IGNORE INTO notifications (user_id, kind, body, link, sms, created_at, dedupe_key)
SELECT x.uid, 'change', x.body, x.link, 0, x.at, 'seed:change:' || x.sid || ':' || x.uid FROM (
  SELECT st.user_id AS uid, s.id AS sid, s.approved_at AS at,
         CASE WHEN s.status = 'approved' THEN 'تغيّر معلّم الحصّة ' || CASE t.period WHEN 1 THEN 'الأولى' WHEN 2 THEN 'الثانية' WHEN 3 THEN 'الثالثة' WHEN 4 THEN 'الرابعة' WHEN 5 THEN 'الخامسة' WHEN 6 THEN 'السادسة' ELSE 'السابعة' END || ' اليوم'
              ELSE 'الحصّة ' || CASE t.period WHEN 1 THEN 'الأولى' WHEN 2 THEN 'الثانية' WHEN 3 THEN 'الثالثة' WHEN 4 THEN 'الرابعة' WHEN 5 THEN 'الخامسة' WHEN 6 THEN 'السادسة' ELSE 'السابعة' END || ' اليوم تعلّم ذاتي موجَّه: ' || s.lesson_note END AS body,
         '/timetable?date=' || a.date || '&section_id=' || t.section_id AS link
  FROM substitutions s JOIN absences a ON a.id = s.absence_id JOIN timetable t ON t.id = s.timetable_id JOIN students st ON st.section_id = t.section_id
  WHERE a.date = (SELECT d FROM demo_days WHERE rn = 1) AND s.status IN ('approved', 'self_study')
  UNION
  SELECT DISTINCT st.guardian_user_id, s.id, s.approved_at,
         CASE WHEN s.status = 'approved' THEN 'تغيّر معلّم الحصّة ' || CASE t.period WHEN 1 THEN 'الأولى' WHEN 2 THEN 'الثانية' WHEN 3 THEN 'الثالثة' WHEN 4 THEN 'الرابعة' WHEN 5 THEN 'الخامسة' WHEN 6 THEN 'السادسة' ELSE 'السابعة' END || ' اليوم'
              ELSE 'الحصّة ' || CASE t.period WHEN 1 THEN 'الأولى' WHEN 2 THEN 'الثانية' WHEN 3 THEN 'الثالثة' WHEN 4 THEN 'الرابعة' WHEN 5 THEN 'الخامسة' WHEN 6 THEN 'السادسة' ELSE 'السابعة' END || ' اليوم تعلّم ذاتي موجَّه: ' || s.lesson_note END,
         '/timetable?date=' || a.date || '&section_id=' || t.section_id
  FROM substitutions s JOIN absences a ON a.id = s.absence_id JOIN timetable t ON t.id = s.timetable_id JOIN students st ON st.section_id = t.section_id
  WHERE a.date = (SELECT d FROM demo_days WHERE rn = 1) AND s.status IN ('approved', 'self_study') AND st.guardian_user_id IS NOT NULL
) x;

INSERT OR IGNORE INTO notifications (user_id, kind, body, link, sms, created_at, dedupe_key)
SELECT st.guardian_user_id, 'absence', 'غياب ' || CASE WHEN u.name LIKE 'عبد %' OR u.name LIKE 'محمد نور %' OR u.name LIKE 'نور الدين %'
                        THEN substr(u.name, 1, instr(u.name, ' ') + instr(substr(u.name, instr(u.name, ' ') + 1), ' ') - 1)
                        ELSE substr(u.name, 1, instr(u.name, ' ') - 1) END || ' اليوم — الحصّة الأولى',
       '/attendance?date=' || a.date || '&student_id=' || st.id, 0, a.created_at, 'seed:absence:' || st.id || ':' || a.date
FROM attendance a JOIN students st ON st.id = a.student_id JOIN users u ON u.id = st.user_id
WHERE a.date = (SELECT d FROM demo_days WHERE rn = 1) AND a.period = 1 AND a.status = 'absent' AND st.guardian_user_id IS NOT NULL;

